import type { CSSProperties } from "react"
import { cn } from "@/lib/utils"

export interface IconProps {
  color?: string
  size?: number
  sizeMobile?: number
  sizeDesktop?: number
  className?: string
}

function getResponsiveIconDimensions(
  {
    size,
    sizeMobile,
    sizeDesktop,
  }: Pick<IconProps, "size" | "sizeMobile" | "sizeDesktop">,
  defaultSize = 24
) {
  const finalSize = size ?? sizeDesktop ?? sizeMobile ?? defaultSize
  const isResponsive = Boolean(sizeMobile || sizeDesktop)

  return {
    finalSize,
    svgClassName: isResponsive ? "vetai-icon-responsive" : "",
    svgStyle: isResponsive
      ? ({
          "--vetai-icon-size-mobile": `${sizeMobile ?? sizeDesktop ?? size ?? defaultSize}px`,
          "--vetai-icon-size-desktop": `${sizeDesktop ?? sizeMobile ?? size ?? defaultSize}px`,
        } as CSSProperties)
      : undefined,
  }
}

